INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(97224, 'ruRU', '', 'Так ты хочешь сказать мне, что не только не смогла захватить хранилище, но даже деревню взять не сумела?', 24330),
(97225, 'ruRU', '', 'Моя Тёмная Госпожа, местные врайкулы оказались грознее, чем ожидалось.', 24330),
(97226, 'ruRU', '', 'Грозными для тебя, возможно. Посмотрим, как они справятся, столкнувшись с Королевой банши!', 24330),
(97227, 'ruRU', '', 'Конечно, Тёмная Госпожа.', 24330),
(97240, 'ruRU', '', 'Должна похвалить тебя за то, что покончила с этим жалким воргеном, Седогривом.\n\nЕдинственное моё сожаление — что меня не было рядом, чтобы увидеть его последние муки.', 24330),
(97241, 'ruRU', '', 'Должна похвалить тебя за то, что покончила с этим жалким воргеном, Седогривом.\n\nЕдинственное моё сожаление — что меня не было рядом, чтобы увидеть его последние муки.', 24330),
(97266, 'ruRU', '', 'Йоу! Думаю, смогу завести тот Разрушитель снаружи и запустить его, если считаешь, что это безопасно!', 24330),
(97269, 'ruRU', '', 'Ладно, босс, но лучше прикрой мой фланг!', 24330),
(97275, 'ruRU', '', 'Я сваливаю отсюда! Удачи спасать мир, босс!', 24330),
(97293, 'ruRU', '', 'Легион падёт.', 24330),
(97301, 'ruRU', '', 'Командир, если хочешь продолжить борьбу, остальные поля сражений по всему Танаану теперь созрели для завоевания.', 24330),
(97302, 'ruRU', '', 'Инициатива на нашей стороне, командир. Тебе стоит штурмовать остальные поля боя по джунглям.', 24330),
(97303, 'ruRU', '', 'Ещё одна славная победа! Если твоя кровь всё ещё кипит, знай — остальные поля боя Танаана созрели, только сорви...', 24330),
(97304, 'ruRU', '', 'Нужно продолжать давить, командир. Остальные горячие точки по всему Танаану теперь уязвимы для атаки.', 24330),
(97307, 'ruRU', '', 'Ещё один триумф Альянса! Тебе стоит развить наше преимущество и атаковать одну из других горячих точек Танаана.', 24330),
(97308, 'ruRU', '', 'Отлично сделано, командир. Разведчики рангари докладывают, что остальные поля боя по всему Танаану теперь уязвимы.', 24330),
(97309, 'ruRU', '', 'Ты заставил прислужников Гул''дана метаться в панике, командир. Подумай об атаке на другие поля боя Танаана, пока они отступают.', 24330),
(97310, 'ruRU', '', 'Продолжай славную борьбу, командир! По всему Танаану есть и другие горячие точки, уязвимые для атаки.', 24330),
(97313, 'ruRU', '', 'Говорю тебе, Алистер, мне это совсем не нравится. Разве ты не помнишь восстание Плети там, в Гилнеасе?', 24330),
(97320, 'ruRU', '', 'Глупцы. Эта гора наша!', 24330),
(97321, 'ruRU', '', 'За Великого Ползуна!', 24330),
(97322, 'ruRU', '', 'Вам не выстоять против мощи наших шабашей.', 24330),
(97323, 'ruRU', '', 'Твой труп накормит моих детёнышей.', 24330),
(97324, 'ruRU', '', 'Я сотворю такие чудесные заклинания из твоих костей.', 24330),
(97325, 'ruRU', '', 'Ползун обрушивается на вас всех!', 24330),
(97326, 'ruRU', '', 'У меня есть новое заклинание специально для тебя.', 24330),
(97327, 'ruRU', '', 'Небеса принадлежат Ползуну!', 24330),
(97333, 'ruRU', '', 'Не только племя Небесного Рога страдает от рук гарпий.\n\nДикая природа, родная для этих гор, страдает от жестокости и хаоса ведьм, и без Морашу, направляющего их духов, им никогда не обрести покой.', 24330),
(97337, 'ruRU', '', 'Морашу обитает в этих горах столько же, сколько любое из племён. Его присутствие необходимо для свершения цикла жизни и смерти, что удерживает природу в равновесии.\n\nГоворят, Морашу направляет духов животных, когда их жизнь подходит к концу. Он рядом с ними, когда свет покидает их глаза, и ведёт их по пути, где их духи вновь сольются с природой.', 24330),
(97338, 'ruRU', '', 'Генн отдыхает.$B$BНам стоит сосредоточиться на установлении связи с флотом и выходе к укреплённой позиции.', 24330),
(97343, 'ruRU', '', 'Смотри, это $n! Я говорил тебе, что именно $Gего:её; изберут. А теперь плати!', 24330),
(97352, 'ruRU', '', 'Мы уже мертвы, идиот!', 24330),
(97367, 'ruRU', '', '$GОн просыпается:Она просыпается;!', 24330),
(97371, 'ruRU', '', 'Хорошо. $GОн:Она; может сражаться?', 24330),
(97378, 'ruRU', '', 'Г-г-где все?', 24330),
(97397, 'ruRU', '', 'Я разорву твоего жалкого воргена на части, Седогрив!', 24330),
(97398, 'ruRU', '', 'Ты заплатишь за своё вмешательство!', 24330),
(97400, 'ruRU', '', 'Смерть ждёт вас всех!', 24330),
(97401, 'ruRU', '', 'Твоя жизнь заканчивается здесь, пёс!', 24330),
(97402, 'ruRU', '', 'Довольно!', 24330);
